-- =====================================================================
-- SEED – chuyển dữ liệu từ Humidity_Inspection_System_FINAL_v4.xlsm
-- Sinh tự động bởi scripts/make-seed.ts. Chạy SAU 0001_schema.sql, 1 lần, trong Supabase > SQL Editor.
-- Gồm: Settings, 11 store, 30 brand map, 279 dòng Lịch sử,
--      739 lô tồn (báo cáo bao-cao_2026-10-19.xlsx), 51 lô kế hoạch đang mở + 202 thùng mẫu.
-- Chạy lại an toàn: dòng đã có sẽ được bỏ qua (riêng tồn kho theo lô được ghi đè).
-- =====================================================================
begin;

update public.settings set
  hum_limit = 6.5, sample_rate = 0.02, readings_per_carton = 3,
  rain_start = 5, rain_end = 10, iso_weeks_rain = 4, iso_weeks_dry = 6,
  preship_earliest = 7, preship_deadline = 5, plan_lookahead = 14,
  plan_date_override = null, grade_filter = 'A', warehouse_sheet = 'FGs_Report',
  mail_subject = 'Daily Stock Report THV-WH', form_warehouse = 'EHV – FG Warehouse',
  last_imported_file = 'bao-cao_2026-10-19.xlsx', last_import_time = '2026-10-19 14:18:03+07',
  updated_at = now()
where id = 1;

on conflict (store_name) do update set include = excluded.include, rows_in_report = excluded.rows_in_report;
on conflict (brand_name) do update set brand_code = excluded.brand_code, note = excluded.note;
on conflict do nothing;
on conflict do nothing;
values ('bao-cao_2026-10-19.xlsx', '2026-10-19', 'seed', 54729, 51848, 739,
  '{"note":"Chuyển từ file Excel v4"}', '2026-10-19 14:18:03+07');
delete from public.stock_lots;
;
;
;
;
on conflict do nothing;
on conflict (plan_id, sample_no) do nothing;
on conflict (plan_id, sample_no) do nothing;
commit;

